    spHomePage: 'සුපිරි බලවතුන්ගේ පිටුව',
    spNameBoost: 'බූස්ට්',
    spDescBoost: 'Home Feed එකේ උඩම තට්ටුවේ තියෙන පෝස්ටුවක් දාන්න.',
    spNameSecondWind: 'දෙවන සුළඟ',
    spDescSecondWind: 'සතියකට වඩා පැරණි පෝස්ටුවක් නැවත ආහාරයේ ඉහළට යවන්න.',
    spNameCommentAnchor: 'Comment නැංගුරම්',
    spDescCommentAnchor: 'වෙන කෙනෙක්ගේ ත් රෙඩ් එකක් දාන්න. කතුවරයෙකුට දැනටමත් ඔවුන්ගේම තනතුරක් ඇත — මෙය ඔබේ, ඔවුන්ගේ නූල් මත වන අතර එය කල් ඉකුත් වේ.',
