    spDescTrendJacker: 'ඔබේ එක් කාණ්ඩයක් ප් රවණතා ලැයිස්තුවේ තබන්න, එහිදී මුළු වේදිකාවම දැනටමත් සොයමින් සිටී.',
    spNameTimelineBomber: 'ටයිම් ලයින් බෝම්බකරු',
    spDescTimelineBomber: 'ඔබේ අනුගාමිකයන් වෙනත් කිසිවෙකුගේ තල්ලුවකට පෙර ඔබේ තනතුර දකී, එබැවින් ඔබෙන් ඇසීමට තෝරාගත් පුද්ගලයින් සඳහා මෙගාලොඩෝනයකට එරෙහිව කෝබ්රා රජු දිනුම් ඇදීම ජය ගනී.',
    spNameSignalFlare: 'සිග්නල් ෆ්ලේයර්',
    spDescSignalFlare: 'එක පෝස්ටුවක් ගැන ඔබේ අනුගාමිකයන්ට දැනුම් දීමක්. එය වෙනම සං signal ා දීමනාවක් වැය කරයි, ඔබේ තල්ලුව නොවේ.',
    spNameFlakJacket: 'ෆ්ලැක් ජැකට්',
    spDescFlakJacket: 'ඔබේ පශ්චාත් එය ක්රියාත්මක වන අතර downvote-buried කළ නොහැකි — ගොඩ- මත සිට ප්රතිශක්තිය, එකඟ නොවන සිට.',
    spNamePrecisionStrike: 'නිරවද්යතාව වැඩ වර්ජනය',
    spDescPrecisionStrike: 'ඔබේ නම අනුගමනය කරන පුද්ගලයින් වෙත ළඟා වන්න, ඔවුන් ඔබව අනුගමනය කළත් නැතත්.',
    spNameHarpoon: 'හාපූන්',
    spDescHarpoon: 'ඔබ එක් තනතුරක් ගැන තෝරා ගන්නා ලාංඡන ස්ථරවල සිටින සෑම හිමිකරුවෙකුටම දැනුම් දෙන්න. සංඥා දීමනාවෙන් ද ගෙවනු ලැබේ.',
    spNameTeamUp: 'කණ්ඩායම',
    spDescTeamUp: 'වෙනත් ගිණුම් 7 ක් දක්වා මුදල් පසුම්බියේ බලය ඒකාබද්ධ කරන්න. කණ්ඩායමේ සෑම කෙනෙකුම සංචිත ශේෂය අගුළු හරින ලාංඡනය පැළඳ සිටින අතර එයට කිසිදු මුදලක් වැය නොවේ.',
    spNameFrontRow: 'ඉදිරිපස පේළිය',
    spDescFrontRow: 'ඔබේ සජීවී අදියර අදියරයන් ලැයිස්තුගත කරන සෑම මතුපිටක් මතම ධාවනය වන අතරතුර අදියර දුම්රියවල ඉහළම ස්ථානය ගනී.',
    spNameDeepCurrent: 'ගැඹුරු ධාරාව',
    spDescDeepCurrent: 'වෙන කෙනෙක්ගේ පෝස්ට් එකකට කමෙන්ට් එකක් දාන්න. ඉහළම තට්ටුව වන්නේ ඔබේ ළඟාවීම අන් අයට ලබා දීමයි.',
    spLadderTitle: 'සෑම ලාංඡනයක්ම ප් ‍ රදානය කරන දේ',
    spLadderDesc: 'එක් එක් සතිය සඳහා බූස්ට්, සහ එක් එක් ධාවනය කොපමණ කාලයක්. ඔබ ඉහළට යන විට තීරුව කිසි විටෙකත් පහළට නොයන අතර එකතුව සෑම විටම ඉහළට යයි.',
    spColUnlocks: 'අගුළු හරින්න',
    spMinShort: 'මිනි. ක්',
    spNoAllowance: 'දීමනාවක් නැත',
    spQuantityOnly: 'තවත් ළඟා, කිසිදු නව බලය',
    spRotationTitle: 'තව් බෙදාගන්නා ආකාරය',
    spRotationDesc: 'පෑන්ටි වලට වඩා පෑන්ටිය කැරකෙනවා. බූස්ට් කිහිපයක් එකවර ක් රියාත්මක වන විට, එක් එක් නරඹන්නාට බූස්ටරයේ ලාංඡන ස්ථරය විසින් බර පටවනු ලැබේ — ඉහළ ස්ථරයක් බොහෝ විට පෙන්වනු ලබන අතර සෑම කෙනෙකුටම තවමත් ඔවුන් ගෙවන කවුළුව ලැබේ. බූස්ට් එකක් මිලට ගන්නේ මිනිත්තු කිහිපයක් සඳහා හඬ කොටසකි, ආහාරයේ ඉහළ කොටස පමණක් නොවේ.',
    spCycleTitle: 'හැමෝටම එක ඔරලෝසුවක්',
    spCycleDesc: 'මෙම චක් රය දින 14 ක වේදිකාවක් වන අතර එමඟින් සෑම කෙනෙකුගේම දීමනාව එකම වේලාවක නැවත පිරවේ. කිසිවක් පෙරළෙන්නේ නැත. වෙන්කරවා ගැනීම ආරම්භ වීමට පෙර එය අවලංගු කර මිනිත්තු ඔබ ඔවුන්ට ගෙවූ චක් ‍ රයට ආපසු යන්න.',
    spSafetyTitle: 'තල්ලුවකට කළ නොහැකි දේ',
    spSafetyDesc: 'සෑම දිනුම් ඇදීමක්ම ඒ මොහොතේ පවතින බැවින් තනතුරට එරෙහිව නැවත පරීක් ෂා කරනු ලැබේ, එබැවින් එතැන් සිට ඉවත් කර, අවහිර කර හෝ පරිණත ලෙස සලකුණු කර ඇති තනතුරක් කිසි විටෙකත් ආගන්තුකයෙකුගේ ආහාරයට ළඟා නොවේ. පරිණත තනතුරු වෙන්කරවා ගැනීමේදී ද ප් ‍ රතික්ෂේප කරනු ලබන අතර, ඔබව අවහිර කර ඇති කෙනෙකුට හෝ ඔබ ඉහළ නංවා ඇති පුද්ගලයාට කිසි විටෙකත් තල්ලුවක් ලබා නොදේ.',
