      'අගුළු හැරීමේ දිනයට පෙර, පරිශීලකයින්ට ඔවුන්ගේ තැන්පත් කළ ටෝකන වලින් 88% ක් පමණක් ඉවත් කළ හැකිය. ඔවුන් අගුළු හැරීමේ දිනයට ළඟා වූ පසු, ඔවුන්ට ගාස්තු රහිතව කොටස් ඉවත් කිරීමට හෝ නැවත ලබා ගැනීමට තෝරා ගත හැකිය.',
      'පරිශීලකයින් නොසැලකිලිමත් වූ විට, ඔවුන්ට ඔවුන්ගේ මුල් ටෝකන වෙන් කිරීම ආපසු ලැබෙනු ඇත.',
