      'DeHub කණ්ඩායම් අරමුදල් ඕනෑම වේලාවක දීමනා, පරිශීලකයින්ට වහාම දීමනා ලැබේ.',
      'පරිශීලකයින්ට කිසිවක් නොමැති නම්, ඔවුන්ට ඕනෑම වේලාවක ඔවුන්ගේ දීමනා ඉල්ලා සිටිය හැක.',
      'පරිශීලකයින්ට වත්මන් ත් ‍ යාග කාල සීමාව තුළ ඔවුන්ගේ ඔට්ටු තැබූ මුදල වැඩි කළ හැකි නමුත් මෙය ලබා ගත හැක්කේ 3 වන ස්ථරය සඳහා පමණි.',
