    formulaLine3: 'පරිශීලකයාගේ කොටස් ප් ‍ රමාණය = 100% * කොටස් ප් ‍ රමාණය',
    formulaLine4: 'දීමනා = කොටස් බෙදාගැනීම * අරමුදල් සපයන ත් ‍ යාග * ස්ථර ප් ‍ රතිශතය',
    example: 'උදාහරණය:',
