    restakeRules: 'රීති නැවත සකසන්න',
    restakeDesc: 'අස්වැන්න නෙළීමේදී පරිශීලකයින්ට ස්වයංක් රීය හෝ අතින් විවේක ගැනීම තෝරා ගත හැකිය. ස්වයංක් ‍ රීයව නැවත ලබා ගැනීම සඳහා, නැවත ලබා ගැනීමේ බොත්තම ක්ලික් කර දම්වැල මත මැජික් දිග හැරෙන විට බලා සිටින්න. අත්පොත ක්රියාවලිය සඳහා, හුදෙක් unstake, ටික ඔබේ metamask සමග ගැන සෙල්ලම් පසුව මුල් ඔට්ටු ක්රියාවලිය අනුගමනය.',
    importantNotes: 'වැදගත් සටහන්:',
