    restakeNote2: 'පරිශීලකයින්ට අගුළු හැරීමේ දිනයට ළඟා වීමට පෙර ස්වයංක් ‍ රීය නැවත ලබා ගැනීමේ බොත්තම භාවිතා කළ හැකි නමුත් මෙය අස්වැන්න නෙළන දිනට වඩා 12% ක ගාස්තුවකින් පැමිණේ.',
