    disclaimerText: 'DeHub ටෝකන ක් රීඩාවේ හෝ යෙදුම තුළ ඩිජිටල් ටෝකන හෝ මුදල් හා දැඩි ලෙස ආයෝජනයක් නොවන ආකාරයටම උපයෝගිතා අරමුණු සඳහා දැඩි ලෙස වේ. අපගේ සංකේත දම්වැල මත ජීවත් වන බැවින්, අපට අතිරේක උපයෝගිතා මෙන්ම සත් යාපනය කළ හැකි විනිවිදභාවයේ පෙර නොවූ විරූ මට්ටම් ලබා දිය හැකිය. ඉහත දත්ත සම්පාදනය කර ඇත්තේ විනිවිදභාවය, අධ් යාපනික හා තොරතුරු අරමුණු සඳහා පමණි. DeHub සහ සියලුම අනුබද්ධ සමාගම් අප නිදහස් කරන ඕනෑම ටෝකනයක් හෝ NFT මිලදී ගැනීමෙන් සිදුවන මූල් ‍ ය අලාභ සඳහා කිසිදු වගකීමක් දරන්නේ නැත. විශේෂයෙන්ම අපි වගේ පුංචි කාලෙදි මේ අය හරිම ආත්මාර්ථකාමීයි. හැකර්, නිපුණතා අසමත් වීම හෝ තාක්ෂණික දෝෂයක් හේතුවෙන් ඔබට ඔබේ සියලු මුදල් අහිමි විය හැකිය. එමනිසා, ඔබ වියදම් කළ යුත්තේ ඔබට අහිමි විය හැකි දේ පමණි.',
