    challengesDesc: 'ප් ‍ රවාහ සහ සූදු වේදිකා සඳහා කේන්ද් ‍ රීය යටිතල පහසුකම් ඉහළ මෙහෙයුම් පිරිවැය, පරිමාණය කිරීමේ සීමාවන් සහ වාරණයට හෝ ඇනහිටීම්වලට ගොදුරු වීමේ හැකියාව වැනි අභියෝගයන්ට මුහුණ දෙයි. පිරිවැය කාර්යක්ෂමතාව පවත්වා ගනිමින් සදහටම දාමයේ ජීවත් වන විමධ් යගත, අවසරයකින් තොරව සහ පරිශීලකයින්ට අයත් ප් රොටෝකෝලයක් වීමේ අරමුණ සාක්ෂාත් කර ගැනීමට DeHub වැනි වේදිකාවලට ඇති හැකියාව මෙම අභියෝගයන් බාධා කරයි.',
