    solutionDesc: 'යටිතල පහසුකම් විමධ් යගත කිරීමෙන්, DeHub හට මෙම අභියෝගයන්ට මුහුණ දීම සඳහා බෙදා හරින ලද පරිගණක බල ජාලයකට තට්ටු කළ හැකිය. ඩෙපින් මඟින් පරිශීලකයින්ට ඔවුන්ගේ පරිගණක සම්පත් බෙදා ගැනීමට ඉඩ සලසයි:',
    costEfficiency: 'පිරිවැය කාර්යක්ෂමතාව:',
    costEfficiencyDesc: 'හවුල් සම්පත් භාවිතා කිරීමෙන් සත්කාරකත්වය සහ බෙදා හැරීමේ පිරිවැය අඩු කරන්න.',
