    povrDesc1: 'අපගේ වෙළඳ දැන්වීම් තාක් ෂණ විසඳුම උරුමය හෝ බ්ලොක්චේන් වෙළඳපල හරහා දක්නට ලැබෙන වෙනත් ඕනෑම දෙයකට වඩා වෙනස් වන අතර අපගේ යෙදුම තුළ අද්විතීය අරමුණක් ඉටු කරයි.',
    povrDesc2: '"දැක්ම පිළිබඳ සාක්ෂි" යනු එක් මානයක් වන අතර හඳුනා ගැනීමෙන් ඔබ්බට, පරිශීලකයින්ට හෝ දරන්නන්ට සුළු ප් රතිලාභයක් එක් කරයි.',
    povrDesc3: 'බ්ලොක් අවකාශය හෝ ගෑස් නාස්ති නොකර ප් ‍ රේක්ෂකයින් සැබෑ බව ඔප්පු කළ හැකි නම් කුමක් කළ යුතුද? ඔබට එක් එක් පසුම්බියේ මූල් ‍ ය දත්ත උත්තේජනය කළ හැකි නම් කුමක් කළ යුතුද, පිරිවැය ඉතිරි කිරීම සඳහා පමණක් නොව, ඔබේ ව් ‍ යාපාර සඳහා ROI උපරිම කිරීමටද? තවත් මුදල් ඉතිරි නොකරන්න, තවත් කරන්න!',
    povrDesc4: 'අපගේ මෘදුකාංගය, පේටන්ට් බලපත් ‍ ර අපේක්ෂිතව, මෙය පෙර නොවූ විරූ 13-ස්ථර ශ් ‍ රේණිගත කිරීමේ පද්ධතියක් හරහා අපගේ සත් ‍ යාපන ලාංඡන සමඟ ඒකාබද්ධ කර ඇත, ඒවා මෙම පෙර විශේෂාංගයේ ඉස්මතු කර ඇත.',
    povrDesc5: 'අපි එය හඳුන්වන්නේ "සාක් ‍ ෂි සහිත දර්ශන හා ශ් ‍ රේණිගත කිරීම්" හෝ "POVR" ලෙසයි.',
    problemTitle: 'ප් ‍ රශ්නය',
    problemDesc: '2023-2024 සඳහා ඇස්තමේන්තු සමඟ වෙළඳ දැන්වීම් වංචා ව් ‍ යාපාර සඳහා වාර්ෂිකව බිලියන ගණනක් වියදම් කරයි',
    problemAmount: '$ 84 බිලියන වසරකට $ 125 බිලියන ඉක්මවා',
    problemDesc2: '2028 වන විට එය $ බිලියන 170 දක්වා ඉහළ යනු ඇතැයි අපේක්ෂා කෙරේ. වංචාකරුවන් දැන්වීම් වියදම් සොරකම් කිරීම සඳහා නවීන රොබෝවරු සහ උපක් රම භාවිතා කරන අතර එය ප් රමිතික සහ ROI වලට බලපාන අතර ඩිජිටල් වියදම් වලින් 20-30% ක් බොහෝ විට ව් යාජ ගමනාගමනය සඳහා නාස්ති වේ.',
    keyFigures: 'ප් ‍ රධාන සංඛ් ‍ යා සහ ප් ‍ රවණතා',
