    whyCostly: 'ඇඩ් වංචාව මෙතරම් මිල අධික වන්නේ ඇයි?',
    sophisticatedBots: 'සුඛෝපභෝගී බෝට්ටු:',
    sophisticatedBotsDesc: 'උසස් බොට්ස් මිනිස් හැසිරීම අනුකරණය කිරීම, ව් ‍ යාජ ක්ලික් කිරීම්, වීඩියෝ දර්ශන සහ ආකෘති පත් ‍ ර පිරවීම.',
    incentives: 'දිරි දීමනා:',
    incentivesDesc: 'වෙළඳ දැන්වීම් තාක් ‍ ෂණ වේදිකා ඓතිහාසිකව පරිමාණයෙන් ප් ‍ රතිලාභ ලබා දුන්නේය, අවශ් ‍ යයෙන්ම සැබෑ මිනිසුන් නොවේ, වංචා සඳහා අවස්ථා නිර්මාණය කරයි.',
