    skewedData: 'Skewed දත්ත:',
    skewedDataDesc: 'දූෂිත විශ්ලේෂණ, දුර්වල ව් යාපාරික තීරණවලට මඟ පාදයි.',
    lostRoi: 'රාජපක් ‍ ෂ:',
    lostRoiDesc: 'විශාල ප් රචාරණ ව් යාපාර සමඟ වුවද වෙළඳ නාම අරමුණු සාක්ෂාත් කර ගැනීම වළක්වයි.',
    howItWorks: 'එය ක් ‍ රියා කරන ආකාරය',
    howItWorksDesc1: 'ඔබේ මුළු වත්කම් වැඩි වන තරමට, ඔබ අගුළු හරින ඉහළ ශ් ‍ රේණිගත ලාංඡනය, ඔබ දැන්වීම් වලින් වැඩි වැඩියෙන් උපයන තරමට, සමාගම් ඔබට ප් ‍ රචාරණය කිරීමට වැඩි මුදලක් ගෙවයි.',
    howItWorksDesc2: 'මේ ආකාරයෙන්, එක් පාර්ශවයක් පමණක් නොව සමස්ත පරිසර පද්ධතියම ප් රයෝජනවත් වේ. අන්තර්ගත නිර්මාණකරුවන්, පාරිභෝගිකයින්, හිමියන් සහ ප්ලැට්ෆෝමයේ ප් ‍ රචාරණය කරන සමාගම් සියල්ලම වැඩි ප් ‍ රතිලාභ ලබා ගනී.',
    howItWorksDesc3: 'මූල් ය දත්ත වඩාත්ම ලාභදායී වන අතර අපගේ අද්විතීය ලෙස ප් රේක්ෂකයින් ඉලක්ක කර ගැනීමට භාවිතා කළ හැකි එක් පද්ධතියකට ඒකාබද්ධ වේ. මෙය ඔබට දම්වැලෙන් පිටත කළ හැකි දෙයක් නොවේ, මන්ද බැංකු ප් රකාශන පුද්ගලික වන අතර බ්ලොක්චේන් පොදු වේ.',
    howItWorksDesc4: 'මුහුදේ කුඩා මසුන් සඳහා විශේෂ ගනුදෙනු හෝ වට්ටම් සකස් කිරීමේදී තල්මසුන් සහ විශාල වියදම් කරන්නන් ඉලක්ක කර ගැනීමට හැකිවීම ලොව පුරා වෙළඳ ප් රචාරණ ක් රියා කරන ආකාරය නැවත හැඩගස්වනු ඇත. ඇයි කාටවත් මේක ඕන නැත්තෙ?',
    preventFraud: 'මෙය වංචාව වළක්වා ගන්නේ කෙසේද?',
    preventFraudDesc1: 'ක් රියාකාරකම් දාමයේ ලුහුබැඳිය හැකි අතර, නරක නළු නිළියන් පහසුවෙන් සම්බන්ධ කිරීම සහ අවසානයේ මුළු පරිශීලක පදනමමම සකස් කිරීම අඩු ලාභදායී වේ. දැන්වීම්කරුවන් ඉහළ ශ් ‍ රේණි ඉලක්ක කරන අතර, ඉතිරි වංචා ඉතිරිව ඇති අවම නිස්සාරණ අගය පහළ ස්ථරයේ තබයි. ඊට ඉහළින්, අපගේ විමධ් ‍ යගත මධ් ‍ යගත කිරීම වඩාත් කාර්යක්ෂම නීති විරෝධී ක් ‍ රියාකාරකම් හඳුනා ගැනීමට සහ වැළැක්වීමට ඉඩ සලසයි.',
    preventFraudDesc2: 'ප්‍රාදේශීය ආදායම බෙදීම සම්බන්ධයෙන් තොරතුරු අපගේ ප්‍රශ්න පත්‍ර පත්‍රය සහ අපගේ වාර්තා පත්‍රය පිටපත් බලන්න. අප අනුගත වන ලෙස අප අනුගත වන්න.',
    dashboardPreview: 'දැන්වීම්කරු ඩෑෂ්බෝඩය පෙරදසුන',
    dashboardDesc: 'දැන්වීම්කරුගේ දෘෂ්ටි කෝණයෙන් POVR වෙළඳ ප් රචාරණ වේදිකාව අත්විඳින්න. මෙම අන්තර්ක් ‍ රියාකාරී පෙරදසුන DeHub හි වෙළඳ දැන්වීම් සමාගම් සඳහා ලබා ගත හැකි මෙවලම් සහ විශ්ලේෂණ පෙන්වයි.',
