    malBio: "සම්පූර්ණ ස්ටැක් වෙබ් සහ බ්ලොක්චේන් සංවර්ධක, Pixcellor හි AI ව්‍යාපාරික විසඳුම් ගොඩනැගීම, Randstad හි හිටපු ජ්‍යෙෂ්ඨ උපදේශක, ඩොලර් මිලියන 250 ක වෙළඳපල සීමාවක් සහ ඩොලර් මිලියන 10 කට ආසන්න ද්‍රවශීලතා අරමුදලක් සහ වසර 1 ලැබුණු ඩොලර් මිලියන 2 ක ආදායමක් සමඟින් DeHub උච්චතම අවස්ථාවට ගෙන ගියේය. මීට පෙර එක්සත් රාජධානියේ විශාලතම නියෝජිත ආයතනය වන Blue Arrow හි වාර්ෂික ඉහළම බිල්පත් උපදේශකයා සහ එක්සත් රාජධානියේ විශාලතම ඉදිකිරීම් නියෝජිත ආයතනය වන ITS හි සමස්ත කලාප ගොඩනගන්නා.",
    malExp1: "Guide Dogs: අරමුදල් රැස් කිරීමේ කළමනාකරු ලෙස බහු ක්ෂේත්‍ර හරහා 5-10 ක කණ්ඩායමක් සමඟින් ඩොලර් මිලියන 1 ඉක්මවා රැස් කරන ලදී.",
    malExp2: "Randstad: ඩොලර් බිලියන 8 ක වෙළඳපල සීමාවක් සහ ලොව විශාලතම නියෝජිත ආයතනයේ ජ්‍යෙෂ්ඨ උපදේශක.",
    malExp3: "Blue Arrow: එක්සත් රාජධානියේ විශාලතම නියෝජිතායතනයේ විශාලතම බිල්කරු සහ සම්මානලාභී උපදේශක, කාර්ය මණ්ඩලය 600 කට අධික සහ කාර්යාල 70 ක් සමඟ රට පුරා. සෑම සතියකම ඩොලර් 10,000 ඉක්මවන පුද්ගලික ශුද්ධ ආයෝජනයක් නිෂ්පාදනය කිරීම සහ ක්‍රියාවලියේදී දහස් ගණනක් බඳවා ගැනීම, ඕනෑම අවස්ථාවක පූර්ණ හෝ අර්ධකාලීන කාර්ය මණ්ඩලය 100 කට අධික සංඛ්‍යාවක් සිටී.",
    malExp4: "ITS Construction: ප්‍රමුඛතම එක්සත් රාජධානියේ ඉදිකිරීම් නියෝජිතායතනයේ සසෙක්ස් ප්‍රාදේශීය කළමනාකරු. මාස 8 කට අඩු කාලයකදී තමන්ගේම කාර්යාලය මුල සිට ගොඩනගා සතියකට ඩොලර් 5k බවට පත් කළේය, එක්සත් රාජධානියේ කීර්තිමත් ඉදිකිරීම්කරුවෙකු වන Berkeley Homes සමඟ PSL අත්සන් කළේය, ඩොලර් බිලියන 100 ක Horsham ව්‍යාපෘතියේ, Highwood හි සුවිශේෂී සැපයුම්කරු ලෙස ජයග්‍රහණය කළේය.",
    mikeName: "Mike Hales",
    mikeRole: "සහ-ආරම්භක",
    mikeBio: "Rapz හි ආරම්භක සහ ප්‍රධාන විධායක නිලධාරී, ඉහළ UFC සහ බොක්සිං තරු විසින් අනුග්‍රහය දක්වන කැපී පෙනෙන ඉහළ පෙළේ MMA සටන් ඇඳුම් සන්නාමයක්, BKFC සඳහා සුවිශේෂී සැපයුම් හිමිකම් සමඟින්. First Class හි ආරම්භක, එක්සත් රාජධානියේ විශාලතම TikTok හවුල්කාර නියෝජිතායතනය, එක්සත් රාජධානියේ මූලස්ථානයේ TikTok සමඟ සෘජුවම අභ්‍යන්තර නියෝජිතායතන වැඩසටහනේ කොටසක් ලෙස ක්‍රියා කරයි, ස්ට්‍රීමර්වරුන් 1000 කට ආසන්න ප්‍රමාණයක් ලියාපදිංචි කර ඇති අතර එක්සත් රාජධානියේ සහ ආසියාවේ කාර්යාල සමඟ අභ්‍යන්තර විධායක කණ්ඩායම සඳහා සෘජුවම වාර්තා කරයි.",
    mikeExp1: "ඔහුගේ සජීවී විකාශන සමඟ එක්සත් රාජධානියේ ප්‍රස්ථාර මාස 10 ක් මෙහෙයවීමෙන් පසු TikTok විධායකයින් විසින් තෝරා ගන්නා ලදී",
    mikeExp2: "Lean Chad Fight Club සහ Rapz Sport පිටුපස සිටින ඩිජිටල් සහ මිශ්‍ර සටන් කලාකරුවා",
    mikeExp3: "NGNE සමඟ මෑතකදී ඒකාබද්ධ වූ එක්සත් රාජධානියේ ප්‍රමුඛතම කෝබ්‍රා බෑග් සැපයුම්කරුගේ හිමිකරු",
    mikeExp4: "BKFC හි සුවිශේෂී සටන් ආම්පන්න සැපයුම්කරු, Connor Mcgregor ට අයත් වන අතර, එම පුහුණුකරු John Kavanagh යටතේ ද පුහුණුව ලබා ඇත.",
    indiName: "Indi Jay Cammish",
    indiRole: "සහ-ආරම්භක",
    indiBio: "සන්නිවේදන සහ ආයතනික සබඳතා අධීක්ෂණය කරන සමාජ මාධ්‍ය, අන්තර්ගත සහ නර්තන විශේෂඥ. First Class හි සම-ආරම්භක, එක්සත් රාජධානියේ විශාලතම TikTok හවුල්කාර නියෝජිතායතනය, එක්සත් රාජධානියේ මූලස්ථානයේ TikTok සමඟ සෘජුවම අභ්‍යන්තර නියෝජිතායතන වැඩසටහනේ කොටසක් ලෙස ක්‍රියා කරයි.",
    indiExp1: "Mabel වැනි ගෝලීය තරු සමඟ දිගුකාලීන ලෝක සංචාර සඳහා සෘජුවම වැඩ කිරීමේ ඉහළ අත්දැකීම්",
    indiExp2: "2022 ගිම්හානයේදී ඇගේ මහරජාණන් වන එංගලන්තයේ රැජින වෙනුවෙන් The Palace හි Platinum Party උත්සවයේදී රඟ දැක්වීය",
    indiExp3: "First Class හි සම-ආරම්භක, එක්සත් රාජධානියේ විශාලතම TikTok හවුල්කාර නියෝජිතායතනය, එක්සත් රාජධානියේ මූලස්ථානයේ TikTok සමඟ සෘජුවම අභ්‍යන්තර නියෝජිතායතන වැඩසටහනේ කොටසක් ලෙස ක්‍රියා කරයි.",
