    monetizationOwnership: 'ඔබේ අන්තර්ගතයේ පූර්ණ අයිතිය සහ ඉඟි, දායකත්වයන්, එන්එෆ්ටී විකුණුම් සහ වෙනත් බ්ලොක්චේන් මත පදනම් වූ ආදායම් ප් රවාහයන් ඇතුළුව විවිධ යාන්ත් රණ හරහා එය මුදල් උපයා ගැනීමේ අයිතිය ඔබ රඳවා ගනී.',
    communityGovernance: 'ප් ‍ රජා පාලනය සහ අන්තර්ගත මධ් ‍ යගත කිරීම',
    decentralizedModeration: 'විමධ් ‍ යගත මධ් ‍ යස්ථතාව Decentralized moderation',
    decentralizedModerationText: 'DeHub හි අන්තර්ගත මධ් ‍ යස්ථ කිරීම ප් ‍ රජා පාලන යාන්ත් ‍ රණයන් හරහා හසුරුවනු ලැබේ:',
    decentralizedModerationItem1: 'ටෝකන් හිමියන් අන්තර්ගත ප් ‍ රතිපත්ති සහ බලාත්මක කිරීමේ ක් ‍ රියාමාර්ග මත ඡන්දය ප් ‍ රකාශ කරයි',
    decentralizedModerationItem2: 'මධ් ‍ යස්ථ ප් ‍ රතිපත්ති තීරණ සඳහා විනිවිද පෙනෙන, දාම මත ඡන්දය ප් ‍ රකාශ කිරීමේ ක් ‍ රියාවලිය',
    decentralizedModerationItem3: 'ප් ‍ රජා පාලනය මගින් පාලනය වන අභියාචනා ක් ‍ රියාවලිය',
    decentralizedModerationItem4: 'ප් ‍ රතිපත්තිය සකස් කරනු ලබන්නේ තනි ආයතනයක් විසින් නොව පාලනයෙනි; එම ප් ‍ රතිපත්තිය ක්ෂණිකව ක් ‍ රියා කරන නම් කරන ලද උපපරිපාලකවරුන්ට එම ප් ‍ රතිපත්තිය බලාත්මක කිරීම පැවරේ',
    designatedModerators: 'මධ් ‍ යස්ථ Moderators',
    designatedModeratorsText: 'ප් ‍ රජා තේරී පත් වූ පරිපාලකයින් සහ ඉහළ පෙළේ ලාංඡන හිමියන්ට මධ් ‍ යස්ථ අයිතිවාසිකම් පවරා ඇත. ඔවුන්ට අන්තර්ගතය ඉවත් කළ හැකි අතර, පරිපාලන ඡන්දයක් සඳහා බලා නොසිට, අන්තර්ගතය නීති විරෝධී වන, ප් ‍ රජා මාර්ගෝපදේශ උල්ලංඝනය කරන හෝ පරිශීලකයින්ට හානියක් වීමේ අවදානමක් ඇති නොකර, වහාම අපයෝජන ගිණුම් අත්හිටුවීමට හෝ බැහැර කිරීමට හැකිය.',
