    designatedModeratorsItem2: 'නම් කරන ලද උපපරිපාලකවරු වහාම අපයෝජන ගිණුම් අත්හිටුවීමට, සීමා කිරීමට හෝ ස්ථිරවම බැහැර කිරීමට ඉඩ ඇත',
    designatedModeratorsItem3: 'පරිශීලකයින් විසින් ඉදිරිපත් කරන ලද වාර්තා සමාලෝචනය සඳහා නම් කරන ලද උපපරිපාලකවරුන් වෙත යොමු කරනු ලැබේ',
    designatedModeratorsItem4: 'පාලනාධිකාරිය විසින් එම උපපරිපාලකවරුන් බලාත්මක කරන ලද සහ ඔවුන්ගේ තීරණ සමාලෝචනය කිරීමට හෝ ආපසු හැරවීමට හැකි ප් ‍ රතිපත්තිය සකසයි, නමුත් ක් ‍ රියාත්මක කිරීම ක් ‍ ෂණික වේ',
    contentRestrictions: 'අන්තර්ගත සීමා',
