    contentRestrictionsItem1: 'අදාළ නීතියෙන් අර්ථ දක්වා ඇති පරිදි නීති විරෝධී අන්තර්ගතය',
    contentRestrictionsItem2: 'නම් කරන ලද උපපරිපාලකයන් විසින් බලාත්මක කරන ලද ප් ‍ රජා මාර්ගෝපදේශ උල්ලංඝනය කරන අන්තර්ගතය',
    contentRestrictionsItem3: 'වේදිකාවේ ආරක්ෂාවට තර්ජනයක් වන තාක්ෂණික අයාචිත තැපැල් හෝ අනිෂ්ට ක් ‍ රියාකාරකම්',
    rightsYouGrant: 'ඔබ ප් ‍ රදානය කරන අයිතීන්',
    rightsYouGrantText: 'ඔබේ අන්තර්ගතයේ ඇති සියලුම හිමිකම් ඔබ රඳවා තබා ගනී. නුඹට අයිති දේ නුඹට අයිති ය.',
