    licenseToOthers: 'වෙනත් පරිශීලකයින්ට බලපත් ‍ රය',
    licenseToOthersText: 'ප්ලැට්ෆෝමයේ විශේෂාංග මගින් සක් ‍ රීය කර ඇති පරිදි ඔබේ අන්තර්ගතයට ප් ‍ රවේශ වීමට සහ බැලීමට ඔබ සේවාවේ අනෙකුත් පරිශීලකයින්ට අයිතිය ලබා දෙන අතරම, ඔබ සියලු මුදල් ඉපැයීම සහ හිමිකාරිත්ව අයිතිවාසිකම් රඳවා තබා ගනී.',
    accountManagement: 'ගිණුම් කළමනාකරණය',
    terminationByYou: 'ඔබ විසින් අවසන් කිරීම',
    terminationByYouText: 'ඔබගේ පසුම්බිය විසන්ධි කිරීමෙන් සහ වේදිකාව භාවිතා කිරීම නැවැත්වීමෙන් ඔබට ඕනෑම වේලාවක සේවාව භාවිතා කිරීම නැවැත්විය හැකිය.',
    restrictionsByDeHub: 'DeHub විසින් සීමාවන්',
    restrictionsByDeHubText: 'ඕනෑම වේලාවක සේවාවට ප් රවේශ වීම සීමා කළ හැකිය. පහත සඳහන් දෑ සඳහා සීමාවන් පැනවිය හැකිය:',
    restrictionsItem1: 'නීතිමය අනුකූලතා අවශ් ‍ යතා',
    restrictionsItem2: 'ප් ‍ රජා පාලන තීරණ',
