    heading: 'රහස්‍යතා ප්‍රතිපත්තිය',
    paragraph1: 'අපි ඔබේ රහස්‍යතාවට ගරු කරන අතර පුද්ගලික තොරතුරු ආරක්ෂා කිරීමට කැපව සිටිමු.',
    paragraph2: 'සේවා අත්දැකීම වැඩිදියුණු කිරීමට අපි අවම දත්ත රැස් කරමු.',
    paragraph3: 'ඔබේ දත්ත ඔබේ කැමැත්තකින් තොරව තෙවන පාර්ශ්වයන්ට විකිණීම සිදු නොකරයි.',
    paragraph4: 'ඔබේ දත්ත ආරක්ෂා කිරීමට අපි කර්මාන්ත ප්‍රමිති සංකේතනය භාවිතා කරමු.',
    paragraph5: 'ඔබේ දත්ත ප්‍රවේශ වීමට, යාවත්කාලීන කිරීමට හෝ මකා දැමීමට ඔබට අයිතිය ඇත.',
    paragraph6: 'සේවා වැඩිදියුණු කිරීම සඳහා අපි නිර්නාමික භාවිත විශ්ලේෂණ රැස් කළ හැකිය.',
    paragraph7: 'සමහර සේවා ක්‍රියාකාරකම් සඳහා කුකී භාවිතා විය හැකිය.',
    importantNotice: 'වැදගත් දැනුම්දීම',
    disclaimer: 'වියාචනය',
    disclaimerText: 'මෙම රහස්‍යතා ප්‍රතිපත්තිය කලින් දැනුම්දීමකින් තොරව වෙනස් කළ හැකිය.',
    commitmentTitle: 'විමධ් ‍ යගත රහස් ‍ යතා කැපවීම',
    commitmentText: 'DeHub නිර්මාණය කර ඇත්තේ පරිශීලකයින්ගේ පෞද්ගලිකත්වයට සහ දත්ත පරමාධිපත් යයට ප් රමුඛතාවය දෙන විමධ් යගත යෙදුමක් ලෙස ය. මෙම රහස් යතා ප් රතිපත්තිය අපගේ විමධ් යගත පරිසර පද්ධතිය තුළ තොරතුරු හැසිරවිය යුතු ආකාරය පැහැදිලි කරයි.',
    corePrinciple: 'මූලික මූලධර්මය: අපි වැඩ කිරීමට අවශ් ‍ ය අවම ගිණුමක් එකතු කරමු, අපි එය කිසි විටෙකත් විකුණන්නේ නැත, සහ ඔබේ උපාංගයේ හෝ පොදු දාමයක පවතින අතීත සියල්ල.',
    dataCollection: 'දත්ත එකතු කිරීම සහ ගබඩා කිරීම',
    whatWeDoCollect: 'අපි එකතු කරන දේ:',
    doCollectItem1: 'ඔබ පුරනය වී ඇති හැඳුනුම්පත — ඔබ එම මාර්ගවලින් එකක් තෝරා ගන්නේ නම් විද් ‍ යුත් තැපැල් ලිපිනයක් හෝ දුරකථන අංකයක්, හෝ ඔබ සමාජීය වශයෙන් අත්සන් කළහොත් ගූගල් හෝ ඇපල් යන අනන් ‍ යතාවය. Wallet Sign-in එකකින් අපිට දෙන්නෙ ඔයාගෙ Public Address එක විතරයි.',
    doCollectItem2: 'ඔබගේ ගිණුම: පරිශීලක නාමය, පැතිකඩ විස්තර, අවතාරය, ඔබ අනුගමනය කරන අය සහ ඔබ තෝරා ගන්නා සැකසුම්. විවිධ පැතිකඩයන් එක් උපාංගයක් මත වාඩි වී සිටිය හැකි අතර, සෑම එකක්ම එකම ආකාරයකින් ගබඩා කර ඇත.',
    doCollectItem3: 'ඔබ ප් රකාශයට පත් කරන දේ — පළ කිරීම්, අදහස්, උඩුගත කිරීම් සහ ඒවා වටා ඇති පාර-දත්ත — එවිට එය ඔබ ප් රකාශයට පත් කළ පුද්ගලයින්ට සේවය කළ හැකිය.',
    doCollectItem4: 'නිෂ්පාදිතය ක් ‍ රියාත්මක කිරීමට අවශ් ‍ ය දේ: දර්ශනය සහ සම්බන්ධතාවය තනතුරු මත ගණන් ගනී, සහ සැසියක් ආරෝපණය කළ හැකි උපාංග හඳුනාගැනීමක් වන අතර එමඟින් ඔබට ඔබේම ක් ‍ රියාකාරී සැසි දැක අවලංගු කළ හැකිය.',
    doCollectItem5: 'ඔබ මිලදී ගන්නා ඕනෑම දෙයක් සඳහා ගෙවීම් වාර්තා, එය Stripe හරහා හෝ දාම මත පදිංචි යන්න, ගිණුම්කරණය සහ ආරවුල් සඳහා තබා. කාඩ්පත් අංක ස්ට් රයිප් විසින් හසුරුවනු ලබන අතර කිසි විටෙකත් අප වෙත ළඟා නොවේ.',
    doCollectItem6: 'යම් දෙයක් කැඩුණු විට රෝග විනිශ්චය කිරීම, එබැවින් එය නිවැරදි කළ හැකිය.',
    whatWeDontCollect: 'අපි එකතු නොකරන දේ:',
