    howItWorksDesc1: 'සෑම DeHub ගිණුමක්ම සාදා ඇති පසුම්බියක් ඇත. ඔබට එය අපගේ Stripe ද්වාරය හරහා කාඩ්පතක් සමඟ අරමුදල් සැපයිය හැකිය, එය වෙනත් පරිශීලකයෙකුගෙන් ලබා ගත හැකිය, එය වේදිකාවෙන් උපයා ගත හැකිය, නැතහොත් එය ඕනෑම ස්වයං රැකවරණ පසුම්බියකින් තැන්පත් කළ හැකිය — ආරම්භ කිරීමට වෙනම යෙදුමක්, දිගුවක් හෝ බීජ වාක් ‍ යයක් නොමැත. ශේෂයන්, ඉඟි, අගුළු ඇරීම සහ දීමනා සියල්ලම DeHub ටෝකනවල පදිංචි වේ, එබැවින් කප්පාදුවක් සිදු වන සහ ගිණුමක් කැටි කළ හැකි ගෙවීම් ප් රොසෙසරයක් හරහා ගමන් කිරීම වෙනුවට පරිශීලකයින් අතර වටිනාකම් චලනයන් සෘජුවම සිදු වේ.',
