    useRewardsDesc: 'x-2- උපයාගත් ගෙවීම්, නැරඹීමේ ත් ‍ යාග, ප් ‍ රකාශයට පත් කරන ලද අන්තර්ගතයන්, රැෆල්, ක් ‍ රීඩා සහ ප් ‍ රජා ව් ‍ යාපාරවල වරප් ‍ රසාද සියල්ලම නම් කර ඇති අතර DeHub ටෝකන වලින් ගෙවනු ලැබේ.',
