    useAiDesc: 'AI මෙවලම් කට්ටල හරහා DeHub ටෝකන ක් ‍ රෙඩිට් ලෙස වියදම් කරන්න — රූපය, වීඩියෝ, ශ් ‍ රව් ‍ ය සහ නියෝජිත පරම්පරාව — මෙවලමකට වෙනම ග් ‍ රාහකත්වයක් පැවැත්වීම වෙනුවට.',
    useCommerceTitle: 'වෙළඳසැල් සහ වෙළඳපොල',
    useCommerceDesc: 'එක් ශේෂයක් භාවිතයෙන් නිර්මාතෘ වෙළඳසැල් සහ වෙළඳපොළෙන් නිෂ්පාදන, ඩිජිටල් එකතු කළ හැකි, සේවා සහ Phygital NFT මිලදී ගන්න.',
