    useFeesDesc: 'ජාල ගාස්තු ගෙවීම, ප්රොටෝකෝල ආදායම් කොටස සඳහා සමාජ ශාලා මට්ටමේ කොටස්, සහ ප්රොටෝකෝල තීරණ මත ආණ්ඩු ඡන්ද ප්රකාශ කිරීමට DeHub ටෝකන පුළුස්සා දමන්න.',
    profitShareTitle: 'ලාභ බෙදාගැනීම',
    profitShareDesc1: 'DeHub නිර්මාණය කර ඇත්තේ ජාලය භාවිතා කරන පුද්ගලයින් එය අයිති කර ගැනීම සඳහා ය. ප් රොටෝකෝල ආදායම — වේදිකා ගාස්තු, වෙළඳසැල් සහ වෙළඳපල ගාස්තු, වෙළඳ ප් රචාරණ, AI භාවිතය සහ ක් රීඩා ආදායම — නැවුම් ලෙස සැකසූ සැපයුමට වඩා සැබෑ අස්වැන්න බෙදා හැරීම සහ මිලදී ගැනීමේ ආපසු ගෙවීමේ ස්වරූපයෙන් කොටස් හිමියන් වෙත ආපසු ගලා යයි. DeHub ටෝකන හිමිකාරීත්වය යනු DeHub ජාලයේ කොටසක් වන අතර එය වියදම් ශේෂයක් පමණක් නොවේ.',
    profitShareDesc2: 'බෙදාහැරීම් සඳහා අරමුදල් සපයනු ලබන්නේ ප් ‍ රොටෝකෝලය සැබවින්ම උපයන දේ, විචල් ‍ ය පරතරයන් මත වන අතර, ඔට්ටු තැබූ මුදල සහ කාලසීමාව යන දෙකෙන්ම ඔට්ටු ඇල්ලීමේ ස්ථර හරහා බෙදී යයි. දිගුකාලීන කැපවීම සෑම බෙදාහැරීමකින්ම විශාල කොටසක් උපයයි. ස්ථර යාන්ත් ‍ ර විද් ‍ යාව සහ නිශ්චිත දීමනා ගණනය කිරීම සඳහා කොටස බලන්න.',
    pegTitle: 'PEGED මිල සහ ඩෙක්ස් ලැයිස්තුගත කිරීම',
    pegDesc1: 'Dehub token යනු ප් ‍ රයෝජනවත් ටෝකනයකි. යෙදුම තුළ අරමුණු සඳහා එය දැනට ටෝකනයකට $ 0.001 ක් ලෙස සලකනු ලැබේ, එය ෆියට් දොරටුව හරහා මිලදී ගැනීමේදී ඔබ දකින අනුපාතය සහ යෙදුම තුළ මිලකරණය සඳහා භාවිතා කරන අනුපාතය වේ. ජාලය පරිමාණය කරන අතරතුර යෙදුම තුළ ආර්ථිකය ස්ථාවර හා පුරෝකථනය කළ හැකි ලෙස තබා ගැනීම සඳහා එම PEG පවතී — එය අභ් යන්තර ගිණුම්කරණ අනුපාතයක් මිස මහලක්, සහතිකයක් හෝ අනාගත වටිනාකම පිළිබඳ පොරොන්දුවක් නොවේ.',
    pegDesc2: 'විමධ් ‍ යගත හුවමාරුවල සංකේත වෙළඳාම, ද් ‍ රවශීලතා තටාක එම 0.001 මූලික මිලෙන් බහුවිධ දම්වැල් හරහා. විවෘත වෙළඳපොලේ මිල නියම කරනු ලබන්නේ වෙළඳාමෙනි - DeHub විසින් නොවේ — එයින් අදහස් කරන්නේ DeHub ටෝකන ඕනෑම වේලාවක යෙදුම තුළ ඇති Peg ට ඉහළින් හෝ පහළින් වෙළඳාම් කළ හැකි බවයි. DeHub එහි නිල ද් ‍ රවශීලතාවය DEXs මත බීජ කරන අතර එමඟින් සෑම ගනුදෙනුවක්ම දාමයේ ප් ‍ රසිද්ධියේ සත් ‍ යාපනය කළ හැකිය.',
    disclaimer: 'වියාචනය',
    disclaimerNoApy: 'වැදගත්: DeHub ටෝකන පැවැත්වීම අතර DeHub ජාලයේ හිමිකාරිත්වය ලබා දෙන අතර ප්රොටෝකෝල ලාභයේ කොටසකට stakers හිමි වේ, කිසිදු APY, සහතික කළ ප්රතිලාභ අනුපාතයක් සහ කිසිදු ආකාරයක ලාභයක් අපේක්ෂා නොකෙරේ. සියලුම බෙදාහැරීම් සම්පූර්ණයෙන්ම රඳා පවතින්නේ ජාල ක් රියාකාරිත්වය සහ ප් රොටෝකෝලය නිශ්චිත කාල පරිච්ඡේදයක් තුළ සැබවින්ම උපයන ආදායම මත ය. දීමනා පෙර කාල සීමාවට වඩා අඩු විය හැකි අතර ශුන් ‍ ය විය හැක. මෙම පිටුවේ ඇති කිසිවක් ආපසු ගෙවීමක් පිළිබඳ පොරොන්දුවක්, ප් රක්ෂේපණයක් හෝ පිරිනැමීමක් නොවන අතර මෙහි කිසිවක් මූල් ය උපදෙස් නොවේ.',
